def max_chain_length(lst, n):
    sorted_pairs = sorted(lst, key=lambda x: x[1])
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if sorted_pairs[i][0] > sorted_pairs[j][1]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp) if n else 0

