import math

def min_Jumps(n, n2, n3):
    d = n
    jump_length = n2
    if jump_length <= 0:
        raise ValueError("Jump length must be positive")
    if d == 0:
        return 0
    if d % jump_length == 0:
        return d // jump_length
    else:
        if d < jump_length:
            return 2
        else:
            return math.ceil(d / jump_length)

