def find_First_Missing(lst, n, n2):
    arr = list(lst)
    length = len(arr)
    for i in range(length):
        while 1 <= arr[i] <= length and arr[arr[i] - 1] != arr[i]:
            temp = arr[i]
            arr[i], arr[temp - 1] = arr[temp -1], arr[i]
    for i in range(length):
        if arr[i] != i +1:
            return i +1
    return length +1

