def max_sum_of_three_consecutive(lst, n):
    if n == 0:
        return 0
    prev0 = 0
    prev1 = lst[0]
    prev2 = float('-inf')
    for i in range(1, n):
        current0 = max(prev0, prev1, prev2)
        current1 = prev0 + lst[i]
        current2 = prev1 + lst[i]
        prev0, prev1, prev2 = current0, current1, current2
    return max(prev0, prev1, prev2)

