def replace(s, s2):
    if not s:
        return ""
    groups = []
    current_char = s[0]
    current_group = [current_char]
    for c in s[1:]:
        if c == current_char:
            current_group.append(c)
        else:
            groups.append(''.join(current_group))
            current_char = c
            current_group = [c]
    groups.append(''.join(current_group))
    result = []
    for group in groups:
        char = group[0]
        if char in s2:
            result.append(char)
        else:
            result.append(group)
    return ''.join(result)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

