import math

def sum_Square(n):
    if n < 0:
        return False
    max_a = math.isqrt(n)
    for a in range(max_a + 1):
        remaining = n - a * a
        if remaining < 0:
            continue
        b = math.isqrt(remaining)
        if b * b == remaining:
            return True
    return False

