def min_Swaps(s: str, s2: str) -> int:
    if len(s) != len(s2):
        return -1
    if s.count('1') != s2.count('1'):
        return -1
    a = b = 0
    for sc, s2c in zip(s, s2):
        if sc != s2c:
            if sc == '0':
                a +=1
            else:
                b +=1
    if a != b:
        return -1
    return a

