def count_Fac(n):
    def is_prime(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        for i in range(3, int(k**0.5) + 1, 2):
            if k % i == 0:
                return False
        return True

    if n == 1:
        return 0
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    primes_count = len(factors)
    exponents_primes = sum(1 for exp in factors.values() if is_prime(exp))
    return primes_count + exponents_primes

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

