def find_first_occurrence(lst: list, n: int) -> int:
    low = 0
    high = len(lst) - 1
    res = -1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == n:
            res = mid
            high = mid - 1
        elif lst[mid] < n:
            low = mid + 1
        else:
            high = mid - 1
    return res

