    result = []
    start, end = sorted((n, n2))
    for num in range(start, end + 1):
        s = str(num)
        if '0' in s:
            continue
        valid = True
        for c in s:
            d = int(c)
            if num % d != 0:
                valid = False
                break
        if valid:
