def lcs_of_three(s, s2, s3, n, n2, n3):
    dp = [[[0]*(n3+1) for _ in range(n2+1)] for __ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, n2+1):
            for k in range(1, n3+1):
                if s[i-1] == s2[j-1] == s3[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])
    return dp[n][n2][n3]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

