def rgb_to_hsv(r, g, b):
    R = r / 255.0
    G = g / 255.0
    B = b / 255.0

    maxc = max(R, G, B)
    minc = min(R, G, B)
    delta = maxc - minc

    if delta == 0:
        h = 0.0
    else:
        if maxc == R:
            h = ((G - B) / delta) * 60
        elif maxc == G:
            h = ((B - R) / delta + 2) * 60
        else:
            h = ((R - G) / delta + 4) * 60
        h %= 360.0

    s = (delta / maxc * 100) if maxc != 0 else 0.0
    v = maxc * 100

    return (h, s, v)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, rgb_to_hsv(255, 255, 255), (0, 0.0, 100.0))
    check(2, rgb_to_hsv(255,0,0), (0.0, 100.0, 100.0))
    check(3, rgb_to_hsv(0,255,0), (120.0,100.0,100.0))
    check(4, rgb_to_hsv(0,0,255), (240.0,100.0,100.0))
    check(5, rgb_to_hsv(255,255,0), (60.0,100.0,100.0))
