def last(lst, n, n2):
    low = 0
    high = len(lst) - 1
    res = -1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == n:
            res = mid
            low = mid + 1
        elif lst[mid] < n:
            low = mid + 1
        else:
            high = mid -1
    return res

