def sort_by_dnf(lst, n):
    low = 0
    mid = 0
    high = n - 1
    while mid <= high:
        if lst[mid] == 0:
            lst[low], lst[mid] = lst[mid], lst[low]
            low += 1
            mid += 1
        elif lst[mid] == 1:
            mid += 1
        else:
            lst[mid], lst[high] = lst[high], lst[mid]
            high -= 1
    return lst

