def count_duplic(lst):
    if not lst:
        return ([], [])
    groups = []
    current = lst[0]
    count = 1
    for num in lst[1:]:
        if num == current:
            count +=1
        else:
            groups.append((current, count))
            current = num
            count = 1
    groups.append((current, count))
    elements = [g[0] for g in groups]
    counts = [g[1] for g in groups]
    return (elements, counts)

