from collections import Counter

def second_frequent(lst):
    counts = Counter(lst)
    if not counts:
        return None
    max_count = max(counts.values())
    filtered = [v for v in counts.values() if v < max_count]
    if not filtered:
        return None
    second_max = max(filtered)
    candidates = [k for k, v in counts.items() if v == second_max]
    return min(candidates) if candidates else None

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

