def generate_matrix(n):
    mat = [[0]*n for _ in range(n)]
    num = 1
    for layer in range(n // 2):
        # Top row: left to right
        for i in range(layer, n - layer):
            mat[layer][i] = num
            num +=1
        # Right column: top+1 to bottom
        for i in range(layer +1, n - layer):
            mat[i][n - layer -1] = num
            num +=1
        # Bottom row: right-1 to left
        for i in range(n - layer -2, layer -1, -1):
            mat[n - layer -1][i] = num
            num +=1
        # Left column: bottom-1 to top+1
        for i in range(n - layer -2, layer, -1):
            mat[i][layer] = num
            num +=1
    if n % 2 == 1:
        mat[n//2][n//2] = num
    return mat

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, generate_matrix(3), [[1,2,3],[8,9,4],[7,6,5]])
    check(2, generate_matrix(1), [[1]])
    check(3, generate_matrix(2), [[1,2],[4,3]])

