def max_sub_array_sum(lst, n):
    if not lst:
        return 0
    current_max = max_sum = lst[0]
    current_length = 1
    max_length = 1
    for num in lst[1:]:
        if current_max + num >= num:
            current_max += num
            current_length += 1
        else:
            current_max = num
            current_length = 1
        if current_max > max_sum:
            max_sum = current_max
            max_length = current_length
        elif current_max == max_sum and current_length > max_length:
            max_length = current_length
    return max_length

