import heapq

def nth_super_ugly_number(n: int, primes: list[int]) -> int:
    heap = [1]
    visited = {1}
    for _ in range(n - 1):
        current = heapq.heappop(heap)
        for p in primes:
            new_ugly = current * p
            if new_ugly not in visited:
                visited.add(new_ugly)
                heapq.heappush(heap, new_ugly)
    return heapq.heappop(heap)

