def find_platform(lst, lst2, n):
    arrival = sorted(lst)
    departure = sorted(lst2)
    i = j = 0
    platforms = 0
    max_platforms = 0
    while i < n and j < n:
        if arrival[i] <= departure[j]:
            platforms += 1
            if platforms > max_platforms:
                max_platforms = platforms
            i += 1
        else:
            platforms -= 1
            j += 1
    return max_platforms

