def sum_of_odd_Factors(n):
    m = n
    while m % 2 == 0:
        m = m // 2
    sum_div = 0
    for i in range(1, int(m**0.5) +1):
        if m % i == 0:
            if i == m // i:
                sum_div += i
            else:
                sum_div += i + m // i
    return sum_div

