def n_common_words(s, n):
    words = s.split()
    counts = {}
    first_occurrence = {}
    for idx, word in enumerate(words):
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
            first_occurrence[word] = idx
    word_list = [(word, counts[word], first_occurrence[word]) for word in counts]
    sorted_words = sorted(word_list, key=lambda x: (-x[1], x[2]))
    result = [(word, count) for word, count, _ in sorted_words[:n]]
    return result

