def find_longest_conseq_subseq(lst, n):
    num_set = set(lst)
    max_length = 0
    for num in num_set:
        if (num - 1) not in num_set:
            current_num = num
            current_length = 1
            while current_num + 1 in num_set:
                current_num += 1
                current_length += 1
            max_length = max(max_length, current_length)
    return max_length

