def remove_list_range(lst, n, n2):
    lower = min(n, n2)
    upper = max(n, n2)
    result = []
    for sub in lst:
        valid = True
        for num in sub:
            if not (lower <= num <= upper):
                valid = False
                break
        if valid:
            result.append(sub)
    return result

