def is_Isomorphic(s: str, s2: str) -> bool:
    if len(s) != len(s2):
        return False
    s_to_s2 = {}
    s2_to_s = {}
    for a, b in zip(s, s2):
        if a in s_to_s2:
            if s_to_s2[a] != b:
                return False
        else:
            if b in s2_to_s:
                if s2_to_s[b] != a:
                    return False
            s_to_s2[a] = b
            s2_to_s[b] = a
    return True

