def no_of_subsequences(lst, n):
    lst.sort()
    k = n
    def backtrack(index, current_product):
        if index == len(lst):
            return 0
        exclude = backtrack(index + 1, current_product)
        num = lst[index]
        new_product = current_product * num
        if new_product >= k:
            include = 0
        else:
            include = 1 + backtrack(index + 1, new_product)
        return exclude + include
    return backtrack(0, 1)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

