def find_Min_Sum(n):
    min_sum = float('inf')
    sqrt_n = int(n ** 0.5)
    for a in range(2, sqrt_n +1):
        if n % a == 0:
            b = n // a
            current_sum = a + b
            if current_sum < min_sum:
                min_sum = current_sum
    return min_sum if min_sum != float('inf') else 1 + n

