def modular_sum(lst, m):
    reachable = set()
    for num in lst:
        mod_num = num % m
        if mod_num == 0:
            return True
        temp = {mod_num}
        for r in reachable:
            new_r = (r + mod_num) % m
            temp.add(new_r)
        reachable.update(temp)
        if 0 in reachable:
            return True
    return False

