def radix_sort(lst):
    if not lst:
        return []
    max_num = max(lst)
    exp = 1
    while max_num // exp > 0:
        buckets = [[] for _ in range(10)]
        for num in lst:
            digit = (num // exp) % 10
            buckets[digit].append(num)
        lst = [num for bucket in buckets for num in bucket]
        exp *= 10
    return lst

