def lbs(lst):
    n = len(lst)
    if n == 0:
        return 0
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if lst[j] < lst[i]:
                lis[i] = max(lis[i], lis[j] + 1)
    lds = [1] * n
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            if lst[j] < lst[i]:
                lds[i] = max(lds[i], lds[j] + 1)
    max_length = 0
    for i in range(n):
        current = lis[i] + lds[i] - 1
        if current > max_length:
            max_length = current
    return max_length

