    words = s.split()
    processed = []
    for word in words:
        if not word:
            processed.append(word)
            continue
        first = word[0].upper()
        last = word[-1].upper()
        middle = word[1:-1].lower()
        new_word = first + middle + last
        processed.append(new_word)
