def find_Max(lst, n, n2):
    low = n
    high = n2
    while low < high:
        mid = (low + high) // 2
        if lst[mid] > lst[mid + 1]:
            return lst[mid]
        if lst[mid] < lst[low]:
            high = mid
        else:
            low = mid + 1
    return lst[low]

