def two_unique_nums(lst):
    freq = {}
    first_occurrence = {}
    for idx, num in enumerate(lst):
        if num not in freq:
            freq[num] = 1
            first_occurrence[num] = idx
        else:
            freq[num] += 1
    elements = list(freq.keys())
    elements.sort(key=lambda x: (-freq[x], first_occurrence[x]))
    selected = elements[:2] if len(elements) >=2 else elements[:1]
    return [x for x in lst if x not in selected]

