import re

def find_adverbs(s):
    match = re.search(r'\b([A-Za-z]+ly)\s*', s)
    if match:
        start = match.start(0)
        end = match.end(0)
        word = match.group(1)
        return f"{start}-{end}: {word}"
    return ""

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, find_adverbs("Clearly, he has no excuse for such behavior."), "0-7: Clearly")
    check(2, find_adverbs("No adverbs here"), "")
    check(3, find_adverbs("Quickly and happily"), "0-8: Quickly")

def expensive_items(lst: list, n: int) -> list:
    sorted_items = sorted(lst, key=lambda x: x['price'], reverse=True)
    return sorted_items[:n]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, expensive_items([{'name': 'Item-1', 'price': 101.1}, {'name': 'Item-2', 'price': 555.22}], 1), [{'name': 'Item-2', 'price': 555.22}])
    check(2, expensive_items([{'price': 200}, {'price': 300}], 2), [{'price':300}, {'price':200}])
    check(3, expensive_items([], 5), [])

def list_tuple(lst):
    return tuple(lst)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, list_tuple([5, 10, 7, 4, 15, 3]), (5, 10, 7, 4, 15, 3))

def big_diff(lst):
    return max(lst) - min(lst)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, big_diff([1,2,3,4]), 3)
    check(2, big_diff([5]), 0)
    check(3, big_diff([3,1,2]), 2)

def swap_List(lst):
    if len(lst) >= 1:
        lst[0], lst[-1] = lst[-1], lst[0]
    return lst

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, swap_List([12, 35, 9, 56, 24]), [24, 35, 9, 56, 12])
    check(2, swap_List([]), [])
    check(3, swap_List([5]), [5])
    check(4, swap_List([1,2]), [2,1])

import math

def sum_Of_product(n):
    return math.comb(2 * n, n - 1)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sum_Of_product(3), 15)

def removezero_ip(s):
    return '.'.join([part.lstrip('0') or '0' for part in s.split('.')])

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, removezero_ip("216.08.094.196"), "216.8.94.196")
    check(2, removezero_ip("0.00.001.0"), "0.0.1.0")
    check(3, removezero_ip("0000.000.00.0"), "0.0.0.0")

def diff_even_odd(lst: list[int]) -> int:
    first_even = None
    first_odd = None
    for num in lst:
        if first_even is None and num % 2 == 0:
            first_even = num
        if first_odd is None and num % 2 != 0:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    return first_even - first_odd

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, diff_even_odd([1,3,5,7,4,1,6,8]), 3)
    check(2, diff_even_odd([2,3]), -1)
    check(3, diff_even_odd([3,2]), -1)
    check(4, diff_even_odd([5, 4, 7, 6]), 4 -5)

def min_Swaps(s: str, s2: str) -> int:
    a = 0
    b = 0
    for sc, s2c in zip(s, s2):
        if sc != s2c:
            if sc == '0':
                a += 1
            else:
                b += 1
    return a

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, min_Swaps("1101", "1110"), 1)

import sys

def tuple_size(tup):
    return sys.getsizeof(tup)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    test_case = ("A", 1, "B", 2, "C", 3)
    check(1, tuple_size(test_case), sys.getsizeof(test_case))
    # Additional test case for empty tuple
    check(2, tuple_size( () ), sys.getsizeof( () ))

def sum_average(n):
    total = n * (n + 1) // 2
    average = total / n
    return (total, average)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sum_average(10), (55, 5.5))
    check(2, sum_average(1), (1, 1.0))
    check(3, sum_average(3), (6, 2.0))

def is_Even(n):
    return (n & 1) == 0

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, is_Even(1), False)
    check(2, is_Even(2), True)
    check(3, is_Even(0), True)
    check(4, is_Even(-4), True)
    check(5, is_Even(-5), False)
